<template>
  <main class="paper-shell"><div class="paper-container authors-container">
    <header class="paper-workspace-header"><div><div class="paper-page-eyebrow">Knowledge Base / Authors</div><h1 class="paper-page-title">Scholar profiles</h1><p class="paper-page-description">Search scholars, inspect affiliations and publication records, and resolve duplicate author identities.</p></div></header>
    <LiteratureKnowledgeNav />
    <form class="paper-panel author-search" @submit.prevent="search"><label>Name<input v-model="query" placeholder="Name keyword" /></label><label>Affiliation<input v-model="affiliation" placeholder="Institution keyword" /></label><button class="paper-button primary" :disabled="pending">{{ pending?'Searching…':'Search' }}</button><button class="paper-button" type="button" @click="clear">Clear</button></form>
    <p v-if="error" class="notice error">{{ error }}</p><p v-if="message" class="notice">{{ message }}</p>
    <section v-if="duplicateGroups.length" class="duplicate-summary"><strong>{{ duplicateGroups.length }} duplicate-name groups detected</strong><span>{{ duplicateRecordCount }} records on this page can be inspected and merged by an administrator.</span></section>
    <section class="paper-panel authors-table"><div class="section-heading"><strong>Authors</strong><span>{{ total.toLocaleString() }} records</span></div>
      <table v-if="groups.length"><thead><tr><th>Name</th><th>Institutions</th><th>Papers</th><th>h-index</th><th>ORCID</th><th>Actions</th></tr></thead><tbody>
        <tr v-for="group in groups" :key="group[0].id" :class="{duplicate:group.length>1}"><td><NuxtLink :to="`/literature/authors/${group[0].id}`"><strong>{{ group[0].full_name }}</strong></NuxtLink><span v-if="group.length>1" class="duplicate-tag">{{ group.length }} duplicate records</span></td><td>{{ institutions(group) }}</td><td>{{ paperCount(group) }}<small v-if="group.length>1"> across {{ group.length }} records</small></td><td>{{ group[0].h_index||'—' }}</td><td><a v-if="group[0].orcid" :href="`https://orcid.org/${group[0].orcid}`" target="_blank" rel="noopener">{{ group[0].orcid }}</a><span v-else>—</span></td><td><template v-if="group.length>1"><button @click="inspect(group)">Details</button><button v-if="isAdmin" class="merge" @click="merge(group)">Merge</button></template><NuxtLink v-else class="view" :to="`/literature/authors/${group[0].id}`">View</NuxtLink></td></tr>
      </tbody></table><div v-else class="empty">{{ pending?'Loading authors…':'No authors found.' }}</div>
      <nav class="pagination"><button :disabled="offset===0" @click="page(-1)">Previous</button><span>Page {{ currentPage }} of {{ pageCount }}</span><button :disabled="offset+limit>=total" @click="page(1)">Next</button></nav>
    </section>
    <div v-if="detailOpen" class="modal-backdrop" @click.self="detailOpen=false"><section class="detail-dialog" role="dialog" aria-modal="true" aria-labelledby="duplicate-title"><header><div><span>Author disambiguation</span><h2 id="duplicate-title">Duplicate records</h2></div><button aria-label="Close" @click="detailOpen=false">×</button></header><div class="detail-list"><article v-for="item in duplicateDetails" :key="item.author?.id"><strong>{{ item.author?.full_name }} <small>ID {{ item.author?.id }}</small></strong><dl><div><dt>Papers</dt><dd>{{ item.stats?.total_papers||0 }}</dd></div><div><dt>Institution</dt><dd>{{ item.author?.current_affiliation||'—' }}</dd></div><div><dt>ORCID</dt><dd>{{ item.author?.orcid||'—' }}</dd></div><div><dt>Created</dt><dd>{{ item.author?.created_at||'—' }}</dd></div></dl></article></div></section></div>
  </div></main>
</template>
<script setup>
import '~/assets/paper-platform.css';import LiteratureKnowledgeNav from '~/components/LiteratureKnowledgeNav.vue';import {authState,loadCurrentUser} from '~/utils/auth'
const config=useRuntimeConfig(),router=useRouter(),route=useRoute(),adminApi=useLiteratureAdmin(),query=ref(String(route.query.q||'')),affiliation=ref(String(route.query.affiliation||'')),authors=ref([]),total=ref(0),pending=ref(false),error=ref(''),message=ref(''),offset=ref(Math.max(0,Number(route.query.offset)||0)),limit=25,detailOpen=ref(false),duplicateDetails=ref([]);useHead({title:'Literature Authors - OpenIsle'});const isAdmin=computed(()=>authState.role==='ADMIN')
const groups=computed(()=>{const map=new Map();for(const author of authors.value){const key=String(author.full_name||'').trim().toLowerCase();if(!map.has(key))map.set(key,[]);map.get(key).push(author)}return [...map.values()]});const duplicateGroups=computed(()=>groups.value.filter(group=>group.length>1)),duplicateRecordCount=computed(()=>duplicateGroups.value.reduce((sum,group)=>sum+group.length,0)),currentPage=computed(()=>Math.floor(offset.value/limit)+1),pageCount=computed(()=>Math.max(1,Math.ceil(total.value/limit)))
const endpoint=path=>`${config.public.apiBaseUrl}/api/literature${path}`
const load=async()=>{pending.value=true;error.value='';try{const p=new URLSearchParams({limit:String(limit),offset:String(offset.value)});if(query.value.trim())p.set('q',query.value.trim());if(affiliation.value.trim())p.set('affiliation',affiliation.value.trim());const data=await $fetch(`${endpoint('/explore/authors/list')}?${p}`);authors.value=data.authors||[];total.value=data.total??authors.value.length;await router.replace({query:{q:query.value||undefined,affiliation:affiliation.value||undefined,offset:offset.value||undefined}})}catch(cause){error.value=cause?.data?.message||cause?.message||'Unable to load authors.'}finally{pending.value=false}}
const search=()=>{offset.value=0;load()},clear=()=>{query.value='';affiliation.value='';offset.value=0;load()},page=direction=>{offset.value=Math.max(0,offset.value+direction*limit);load()};const institutions=group=>[...new Set(group.flatMap(author=>author.institutions||[]).filter(Boolean))].slice(0,3).join('; ')||group.find(author=>author.current_affiliation)?.current_affiliation||'—';const paperCount=group=>group.reduce((sum,author)=>sum+Number(author.paper_count||author.total_publications||0),0)
const inspect=async group=>{error.value='';try{duplicateDetails.value=await Promise.all(group.map(author=>$fetch(endpoint(`/explore/author/${author.id}`))));detailOpen.value=true}catch(cause){error.value=cause?.data?.message||cause?.message||'Unable to load duplicate details.'}}
const merge=async group=>{const primary=group[0],duplicates=group.slice(1).map(author=>author.id);if(!confirm(`Merge ${duplicates.length} duplicate record(s) into author ID ${primary.id}?\n\nPaper links will be transferred and duplicate records deleted. This cannot be undone.`))return;pending.value=true;error.value='';message.value='';try{const result=await adminApi.post('/authors/merge',{primary_id:primary.id,duplicate_ids:duplicates});message.value=`Merged ${result.merged_count||duplicates.length} records and transferred ${result.merged_papers||0} paper links.`;await load()}catch(cause){error.value=cause?.data?.message||cause?.message||'Administrator permission is required to merge authors.'}finally{pending.value=false}}
onMounted(async()=>{if(authState.loggedIn&&!authState.role)await loadCurrentUser();await load()})
</script>
<style scoped>
.authors-container{max-width:1180px}.author-search{display:grid;grid-template-columns:1fr 1fr auto auto;gap:10px;align-items:end;padding:15px;margin-bottom:14px}.author-search label{display:grid;gap:5px;color:var(--paper-muted);font-size:11px;font-weight:750}.author-search input{min-height:39px;border:1px solid var(--paper-line);padding:8px 10px}.duplicate-summary{display:grid;gap:3px;margin-bottom:14px;padding:12px 15px;border-left:3px solid #d69819;background:#fff8e6}.duplicate-summary span{color:#71510b;font-size:11px}.authors-table{overflow:hidden}.section-heading{display:flex;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--paper-line)}.section-heading span{color:var(--paper-muted);font-size:11px}.authors-table table{width:100%;border-collapse:collapse}.authors-table th,.authors-table td{padding:11px 14px;border-bottom:1px solid var(--paper-line);text-align:left;font-size:12px}.authors-table th{color:var(--paper-muted);font-size:10px;text-transform:uppercase}.authors-table tr.duplicate{background:#fffaf0}.authors-table a{color:var(--paper-ink);text-decoration:none}.authors-table td:first-child{display:grid;gap:5px}.authors-table small{color:var(--paper-muted)}.duplicate-tag{justify-self:start;padding:2px 6px;background:#f7e8bb;color:#765510;font-size:9px;font-weight:800;text-transform:uppercase}.authors-table td:last-child{white-space:nowrap}.authors-table td button,.view{border:1px solid var(--paper-line);background:#fff;padding:6px 8px;font-size:10px;cursor:pointer}.authors-table td button.merge{margin-left:5px;background:var(--paper-teal);color:#fff}.empty{padding:50px;text-align:center;color:var(--paper-muted)}.pagination{display:flex;justify-content:center;align-items:center;gap:12px;padding:14px}.pagination button{border:1px solid var(--paper-line);background:#fff;padding:7px 10px}.pagination span{color:var(--paper-muted);font-size:11px}.notice{padding:10px 14px;background:#eaf7f1;color:#176b50}.notice.error{background:#fff4f2;color:#8b3028}.modal-backdrop{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:20px;background:rgba(20,34,43,.56)}.detail-dialog{width:min(680px,100%);max-height:80vh;overflow:auto;background:#fff}.detail-dialog header{display:flex;justify-content:space-between;padding:17px 19px;border-bottom:1px solid var(--paper-line)}.detail-dialog header span{color:var(--paper-teal);font-size:9px;font-weight:800;text-transform:uppercase}.detail-dialog h2{margin:4px 0 0;font:500 23px Georgia,serif}.detail-dialog header button{border:0;background:none;font-size:25px}.detail-list{display:grid;gap:1px;background:var(--paper-line)}.detail-list article{padding:15px 18px;background:#fff}.detail-list small{color:var(--paper-muted)}.detail-list dl{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:12px 0 0}.detail-list dt{color:var(--paper-muted);font-size:9px;text-transform:uppercase}.detail-list dd{margin:3px 0 0;font-size:11px}@media(max-width:800px){.author-search{grid-template-columns:1fr 1fr}.authors-table{overflow:auto}.detail-list dl{grid-template-columns:1fr 1fr}}
</style>
